import {START,position,fen,fromSan,play,uci} from './rules.js';
function hash(s){let h=2166136261;for(let c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0).toString(36)}
export function importPgn(text,allowMissing=false){let groups=text.replace(/^\uFEFF/,'').split(/(?=^\s*\[Event\s+")/m).filter(s=>s.trim());if(!groups.length)throw Error('No PGN chapters found.');let lines=groups.map((raw,i)=>{let tags={};for(const m of raw.matchAll(/^\s*\[([^\s]+)\s+"((?:\\.|[^"\\])*)"\s*\]/gm))tags[m[1]]=m[2].replace(/\\(["\\])/g,'$1');let title=tags.StudyName||tags.Event||'Imported course';let name=tags.ChapterName||tags.Site?.split('/').pop()||tags.White||`Line ${i+1}`;if(tags.Event&&tags.Event.includes(':')){let v=tags.Event.split(':');title=v.shift().trim();name=v.join(':').trim();}else if(tags.Event&&tags.Event!=='?'&&tags.StudyName)name=tags.Event;let line={id:'line-'+hash(raw.trim()),name,title,tags,sourcePgn:raw,start:tags.FEN||START,steps:[],warnings:[],error:null};let variant=(tags.Variant||'').toLowerCase();if(variant&&!['antichess','suicide','giveaway','losing chess'].includes(variant)){line.error=`Unsupported variant: ${tags.Variant}`;return line}if(!variant&&!allowMissing){line.error='Variant tag missing; confirm antichess before importing.';return line}try{let p=position(line.start);let body=raw.replace(/^\s*\[[^\n]*\]\s*$/gm,'');let tokens=body.match(/\{[^}]*\}|;[^\n]*|\(|\)|[^\s(){}]+/g)||[];let depth=0,pending='';for(let token of tokens){if(token==='('){depth++;continue}if(token===')'){if(depth>0)depth--;else throw Error('Unmatched variation closing bracket');continue}if(depth)continue;if(token.startsWith('{')||token.startsWith(';')){let c=token.replace(/^\{|\}$/g,'').replace(/^;/,'').trim();if(line.steps.length)line.steps.at(-1).comment=(line.steps.at(-1).comment+' '+c).trim();else pending=(pending+' '+c).trim();continue}token=token.replace(/^\d+\.{1,3}/,'');if(!token||/^\d+\.{1,3}$/.test(token)||/^\$\d+$/.test(token)||/^(1-0|0-1|1\/2-1\/2|\*)$/.test(token))continue;let before=fen(p),m=fromSan(p,token);p=play(p,m);line.steps.push({san:token,uci:uci(m),before,after:fen(p),comment:'',side:before.split(' ')[1]});}if(depth)throw Error('Unclosed variation');line.intro=pending;if(!line.steps.length)line.error='No main-line moves: this chapter is a draft or quiz position.';}catch(e){line.error=e.message;line.steps=[]}return line});let title=lines[0]?.title||'Imported course';return {id:'course-'+hash(title+'|'+(lines[0]?.tags.Site||'')),title,lines};}
